def climbStairs(n: int) -> int:
    """Return number of distinct ways to climb n stairs (1 or 2 steps at a time).

    Shows both memoization and tabulation approaches.
    """
    # Top-down with memoization
    memo = {}

    def climb_memo(i: int) -> int:
        if i <= 1:
            return 1
        if i in memo:
            return memo[i]
        memo[i] = climb_memo(i - 1) + climb_memo(i - 2)
        return memo[i]

    # Bottom-up tabulation
    def climb_tabulation(n: int) -> int:
        if n <= 1:
            return 1
        dp = [0] * (n + 1)
        dp[0], dp[1] = 1, 1
        for i in range(2, n + 1):
            dp[i] = dp[i - 1] + dp[i - 2]
        return dp[n]

    # Space-optimized bottom-up
    def climb_optimized(n: int) -> int:
        if n <= 1:
            return 1
        prev2, prev1 = 1, 1
        for i in range(2, n + 1):
            curr = prev1 + prev2
            prev2, prev1 = prev1, curr
        return prev1

    return climb_optimized(n)
